import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"User & Subscriber Models","description":"","frontmatter":{},"headers":[],"relativePath":"backend/models/user-subscriber.md","filePath":"backend/models/user-subscriber.md"}`),a={name:`backend/models/user-subscriber.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e('<h1 id="user-subscriber-models" tabindex="-1">User &amp; Subscriber Models <a class="header-anchor" href="#user-subscriber-models" aria-label="Permalink to &quot;User &amp; Subscriber Models&quot;">​</a></h1><p>These models handle authentication, authorization, and audience management.</p><h2 id="user-php" tabindex="-1"><code>User.php</code> <a class="header-anchor" href="#user-php" aria-label="Permalink to &quot;`User.php`&quot;">​</a></h2><p>The standard Laravel authenticatable model. In TechyNews, a <code>User</code> typically represents an Administrator or Editor who has access to the <code>/dashboard</code>.</p><p><strong>Key Traits:</strong></p><ul><li><code>HasApiTokens</code> (Sanctum/Passport)</li><li><code>Notifiable</code></li></ul><p><strong>Roles &amp; Permissions:</strong> TechyNews keeps roles simple. Typically, any authenticated <code>User</code> in the database has admin privileges to trigger AI agents, delete articles, and view telemetry.</p><h2 id="subscriber-php" tabindex="-1"><code>Subscriber.php</code> <a class="header-anchor" href="#subscriber-php" aria-label="Permalink to &quot;`Subscriber.php`&quot;">​</a></h2><p>Represents a public user who has opted into the weekly newsletter. They do not have login credentials or a password.</p><p><strong>Columns:</strong></p><ul><li><code>email</code> (String, Unique)</li><li><code>is_active</code> (Boolean): For opt-out management.</li><li><code>locale</code> (String): Saves the user&#39;s preferred language (<code>en</code>, <code>es</code>, <code>pt</code>) so the newsletter can be localized on send.</li></ul><p><strong>Workflow:</strong></p><ul><li>Handled by the <code>SendWeeklyNewsletter</code> console command.</li><li>The command iterates through <code>Subscriber::where(&#39;is_active&#39;, true)-&gt;get()</code>, groups them by <code>locale</code>, and dispatches a customized Mail facade template.</li></ul>',13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};